112:     player.coins += yoKai.reward;
113:     showMessage(`${yoKai.name} ha sido capturado. +${yoKai.reward} monedas.`);
114:   } else if (result === 'escaped') {
115:     showMessage(`${yoKai.name} ha huido a la noche.`);
116:   } else {
117:     player.hp = Math.max(0, player.hp - 10);
118:     showMessage('Te han debilitado. Busca un árbol para curarte.');
119:   }
120: 
121:   const index = yoKaiInWorld.findIndex((entry) => entry.name === yoKai.name && !player.captured.includes(entry.name));
122:   if (index >= 0) {
123:     yoKaiInWorld[index].active = false;
124:   }
125: 
126:   battleState.active = false;
127:   battleState.yoKai = null;
128:   battlePanel.classList.add('hidden');
129:   updateHUD();
130: }
131: 
132: function performBattleAction(action) {
133:   if (!battleState.active || !battleState.yoKai) return;
134: 
135:   const yoKai = battleState.yoKai;
136:   const currentTurn = battleState.turn;
137: 
138:   if (action === 'attack') {
139:     battleState.currentHp -= 12 + Math.floor(Math.random() * 8);
140:     showMessage(`${yoKai.name} recibe un golpe con talón de espíritu.`);
141:   }
142: 
143:   if (action === 'spirit') {
144:     const dmg = 15 + Math.floor(Math.random() * 10);
145:     battleState.currentHp -= dmg;
146:     player.spirit = clamp(player.spirit - 10, 0, 100);
147:     showMessage(`${yoKai.name} se ve afectado por el poder del espíritu.`);
148:   }
149: 
150:   if (action === 'heal') {
151:     player.hp = clamp(player.hp + 16, 0, 100);
152:     player.spirit = clamp(player.spirit + 8, 0, 100);
153:     showMessage('Te curas con una pequeña energía lunar.');
154:   }
155: 
156:   if (action === 'run') {
157:     endBattle('escaped');
158:     return;
159:   }
160: 
161:   battleState.turn += 1;
162:   battleHp.textContent = 'HP: ' + Math.max(0, battleState.currentHp);
163: 
164:   const opponentAttack = 6 + Math.floor(Math.random() * 12);
165:   player.hp = clamp(player.hp - opponentAttack, 0, 100);
166:   hpValue.textContent = player.hp;
167: 
168:   if (battleState.currentHp <= 0) {
169:     endBattle('caught');
170:     return;
171:   }
172: 
173:   if (player.hp <= 0) {
174:     player.hp = 100;
175:     player.spirit = 100;
176:     player.x = 120;
177:     player.y = 170;
178:     endBattle('lost');
179:     return;
180:   }
181: 
182:   showMessage(`Turno ${currentTurn}: ${yoKai.name} contraataca por ${opponentAttack}.`);
183: }
184: 
185: function findNearbyYoKai() {
186:   return yoKaiInWorld.find((yoKai) => yoKai.active && Math.hypot(player.x - yoKai.x, player.y - yoKai.y) < 42);
187: }
188: 
189: function checkInteraction() {
190:   if (battleState.active) return;
191: 
192:   const nearby = findNearbyYoKai();
193:   if (nearby) {
194:     resetBattle(nearby);
195:     return;
196:   }
197: 
198:   const interactable = interactables.find((obj) =>
199:     player.x + player.radius > obj.x &&
200:     player.x - player.radius < obj.x + obj.w &&
201:     player.y + player.radius > obj.y &&
202:     player.y - player.radius < obj.y + obj.h
203:   );
204: 
205:   if (interactable) {
206:     if (interactable.shop) {
207:       player.coins += 5;
208:       showMessage('La tienda de amuletos te regala 5 monedas de la luna.');
209:       updateHUD();
210:     }
211: 
212:     if (interactable.heal) {
213:       player.hp = clamp(player.hp + 20, 0, 100);
214:       player.spirit = clamp(player.spirit + 25, 0, 100);
215:       showMessage('El árbol te devuelve energía.');
216:       updateHUD();
217:     }
218: 
219:     if (interactable.portal) {
220:       const winState = player.captured.length >= 3;
221:       showMessage(winState
222:         ? '¡La puerta del barrio se abre! Has completado la misión.'
223:         : 'La puerta permanece cerrada. Aún faltan espíritus por capturar.');
224:     }
225:   }
226: }
