228: function drawBackground() {
229:   ctx.clearRect(0, 0, world.width, world.height);
230: 
231:   const sky = ctx.createLinearGradient(0, 0, 0, world.height);
232:   sky.addColorStop(0, '#2b325a');
233:   sky.addColorStop(0.7, '#192541');
234:   sky.addColorStop(1, '#0f1527');
235:   ctx.fillStyle = sky;
236:   ctx.fillRect(0, 0, world.width, world.height);
237: 
238:   ctx.fillStyle = '#7abdff';
239:   ctx.beginPath();
240:   ctx.arc(760, 95, 48, 0, Math.PI * 2);
241:   ctx.fill();
242: 
243:   ctx.fillStyle = '#f7d885';
244:   ctx.fillRect(0, 360, world.width, 220);
245: 
246:   ctx.fillStyle = '#4f8a5d';
247:   ctx.fillRect(0, 350, world.width, 30);
248: 
249:   ctx.fillStyle = '#7a573a';
250:   ctx.fillRect(250, 175, 120, 140);
251:   ctx.fillRect(460, 90, 170, 190);
252:   ctx.fillRect(685, 220, 110, 140);
253: 
254:   ctx.fillStyle = '#d9bb7f';
255:   ctx.fillRect(290, 200, 40, 115);
256:   ctx.fillRect(515, 120, 40, 150);
257:   ctx.fillRect(720, 245, 50, 110);
258: 
259:   ctx.fillStyle = '#e7e6f3';
260:   ctx.fillRect(30, 390, 100, 70);
261:   ctx.fillRect(150, 400, 90, 60);
262:   ctx.fillRect(610, 420, 130, 70);
263: 
264:   for (const object of interactables) {
265:     ctx.fillStyle = object.shop ? '#d39dff' : object.heal ? '#90f5a8' : '#f1d67d';
266:     ctx.fillRect(object.x, object.y, object.w, object.h);
267:   }
268: }
269: 
270: function drawYoKai() {
271:   for (const yoKai of yoKaiInWorld) {
272:     if (!yoKai.active) continue;
273:     ctx.fillStyle = yoKai.color;
274:     ctx.beginPath();
275:     ctx.arc(yoKai.x, yoKai.y, 20, 0, Math.PI * 2);
276:     ctx.fill();
277: 
278:     ctx.fillStyle = '#111827';
279:     ctx.font = '18px sans-serif';
280:     ctx.textAlign = 'center';
281:     ctx.fillText(yoKai.emoji, yoKai.x, yoKai.y + 7);
282: 
283:     ctx.fillStyle = '#1f2937';
284:     ctx.fillRect(yoKai.x - 22, yoKai.y - 30, 44, 6);
285:     ctx.fillStyle = '#7ef0a1';
286:     ctx.fillRect(yoKai.x - 22, yoKai.y - 30, 44 * (yoKai.hp / 40), 6);
287:   }
288: }
289: 
290: function drawPlayer() {
291:   const shade = player.facing === 'up' ? '#70d7ff' : player.facing === 'left' ? '#9fd9ff' : '#e9ebff';
292:   ctx.fillStyle = shade;
293:   ctx.beginPath();
294:   ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
295:   ctx.fill();
296: 
297:   ctx.fillStyle = '#0e1b2f';
298:   ctx.fillRect(player.x - 6, player.y - 12, 12, 18);
299: }
300: 
301: function updatePlayer(delta) {
302:   let dx = 0;
303:   let dy = 0;
304: 
305:   if (keys['w'] || keys['arrowup']) { dy -= 1; player.facing = 'up'; }
306:   if (keys['s'] || keys['arrowdown']) { dy += 1; player.facing = 'down'; }
307:   if (keys['a'] || keys['arrowleft']) { dx -= 1; player.facing = 'left'; }
308:   if (keys['d'] || keys['arrowright']) { dx += 1; player.facing = 'right'; }
309: 
310:   const length = Math.hypot(dx, dy) || 1;
311:   dx /= length;
312:   dy /= length;
313: 
314:   player.x = clamp(player.x + dx * player.speed * delta, 20, world.width - 20);
315:   player.y = clamp(player.y + dy * player.speed * delta, 20, world.height - 20);
316: }
317: 
318: function handleKeydown(event) {
319:   keys[event.key.toLowerCase()] = true;
320:   if (event.key === 'e' || event.key === 'E') {
321:     checkInteraction();
322:   }
323: }
324: 
325: function handleKeyup(event) {
326:   keys[event.key.toLowerCase()] = false;
327: }
328: 
329: function bindBattleButtons() {
330:   document.querySelectorAll('[data-action]').forEach((button) => {
331:     button.addEventListener('click', () => {
332:       performBattleAction(button.dataset.action);
333:     });
334:   });
335: }
336: 
337: let lastTime = 0;
338: function gameLoop(timestamp) {
339:   const delta = Math.min((timestamp - lastTime) / 1000 || 0.016, 0.033);
340:   lastTime = timestamp;
341: 
342:   if (!battleState.active) {
343:     updatePlayer(delta);
344:   }
345: 
346:   drawBackground();
347:   drawYoKai();
348:   drawPlayer();
349:   requestAnimationFrame(gameLoop);
350: }
351: 
352: window.addEventListener('keydown', handleKeydown);
353: window.addEventListener('keyup', handleKeyup);
354: bindBattleButtons();
355: updateHUD();
356: requestAnimationFrame(gameLoop);

