:root {
  color-scheme: dark;
  --bg-1: #0c1020;
  --panel: #151c2d;
  --panel-soft: #1c2740;
  --border: rgba(179, 205, 255, 0.2);
  --text: #f3f5ff;
  --muted: #aab6d3;
  --gold: #ffd176;
  --cyan: #79deff;
  --green: #8ef0ad;
}

* { box-sizing: border-box; }

html, body { margin: 0; min-height: 100%; }

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 18px;
  color: var(--text);
  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
  background: radial-gradient(ellipse at 50% 0%, #394774 0%, #171d35 43%, #090c17 100%);
}

button { font: inherit; }

.game-shell {
  width: min(1240px, 100%);
  overflow: hidden;
  border: 1px solid rgba(187, 208, 255, .26);
  border-radius: 22px;
  background: rgba(12, 16, 29, .96);
  box-shadow: 0 28px 80px rgba(0, 0, 0, .48), 0 0 50px rgba(102, 143, 226, .12);
}

.top-bar {
  min-height: 88px;
  padding: 14px 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  background: linear-gradient(110deg, #253451, #172138 72%);
  border-bottom: 1px solid var(--border);
}

.brand { color: var(--gold); font-size: clamp(1.35rem, 3vw, 1.8rem); font-weight: 900; letter-spacing: .035em; text-shadow: 0 2px 0 #805b32; }
.subtitle { margin-top: 2px; color: #b7c8e9; font-size: .68rem; letter-spacing: .2em; text-transform: uppercase; }
.status-row { display: flex; justify-content: flex-end; gap: 9px; flex-wrap: wrap; }
.pill { min-width: 103px; padding: 7px 12px; border: 1px solid var(--border); border-radius: 999px; display: flex; justify-content: center; align-items: center; gap: 9px; background: rgba(9, 15, 29, .45); box-shadow: inset 0 1px rgba(255,255,255,.05); }
.pill span { color: var(--muted); font-size: .65rem; letter-spacing: .08em; text-transform: uppercase; }
.pill strong { color: white; font-size: 1.1rem; }

.game-layout { display: grid; grid-template-columns: 190px minmax(0, 1fr) 230px; align-items: stretch; }
.hud-panel { padding: 18px 15px; background: linear-gradient(180deg, #121827, #101522); }
.left-panel { border-right: 1px solid var(--border); }
.right-panel { border-left: 1px solid var(--border); }
.hud-panel h2 { margin: 0 0 12px; color: var(--cyan); font-size: 1.08rem; }
.hud-panel p { margin: 0; color: #d7dced; font-size: .9rem; line-height: 1.45; }
.small-heading { margin-top: 22px !important; }
.team-list, .guide-list { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 8px; }
.team-list li { padding: 8px 9px; display: flex; justify-content: space-between; gap: 8px; border: 1px solid var(--border); border-radius: 10px; background: rgba(255,255,255,.035); font-size: .82rem; }
.team-list li span:first-child { font-weight: 800; }
.team-list .captured { color: var(--green); }
.guide-list li { padding: 9px 10px; border-left: 3px solid var(--gold); border-radius: 0 9px 9px 0; background: rgba(255,255,255,.035); color: var(--muted); font-size: .82rem; line-height: 1.35; }

.arena-wrap { min-width: 0; position: relative; align-self: center; overflow: hidden; aspect-ratio: 900 / 560; background: #192844; }
#gameCanvas { display: block; width: 100%; height: 100%; }
.message-box { position: absolute; z-index: 2; left: 50%; bottom: 14px; transform: translateX(-50%); width: min(80%, 560px); padding: 10px 14px; border: 1px solid rgba(206, 221, 255, .26); border-radius: 12px; background: rgba(10, 15, 26, .86); box-shadow: 0 6px 22px rgba(0,0,0,.32); color: #f5f6ff; font-size: .88rem; line-height: 1.35; text-align: center; backdrop-filter: blur(6px); }

.battle-panel { margin-top: 16px; padding: 12px; border: 1px solid var(--border); border-radius: 14px; background: linear-gradient(145deg, rgba(48, 62, 92, .48), rgba(255,255,255,.025)); }
.battle-panel.hidden { display: none; }
#battleTitle { margin: 0 0 10px; color: var(--gold); font-size: 1rem; text-align: center; }
.enemy-card { padding: 5px 2px 13px; display: flex; align-items: center; gap: 10px; font-size: .92rem; font-weight: 800; }
.battle-emoji { width: 48px; height: 48px; display: grid; place-items: center; flex: 0 0 auto; border: 1px solid var(--border); border-radius: 14px; background: rgba(255,255,255,.07); font-size: 1.8rem; }
#battleHp { margin-top: 4px; color: var(--muted); font-size: .78rem; font-weight: 500; }
.battle-actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.battle-actions button { min-height: 39px; padding: 8px 5px; border: 1px solid rgba(191, 212, 255, .25); border-radius: 9px; background: linear-gradient(180deg, #34577c, #233653); color: white; font-size: .8rem; font-weight: 800; cursor: pointer; transition: filter .15s, transform .15s; }
.battle-actions button:hover { filter: brightness(1.18); transform: translateY(-1px); }
.battle-actions button:active { transform: translateY(1px); }

.touch-controls { display: none; }

@media (max-width: 920px) {
  body { padding: 10px; }
  .game-layout { grid-template-columns: 165px minmax(0, 1fr) 205px; }
  .hud-panel { padding: 14px 11px; }
  .team-list li, .guide-list li { font-size: .75rem; }
}

@media (max-width: 700px) {
  body { display: block; min-height: 100dvh; padding: max(6px, env(safe-area-inset-top)) 6px max(8px, env(safe-area-inset-bottom)); }
  .game-shell { border-radius: 16px; }
  .top-bar { min-height: 0; padding: 10px 12px; align-items: flex-start; gap: 8px; }
  .brand { font-size: 1.18rem; }
  .subtitle { font-size: .55rem; }
  .status-row { gap: 4px; }
  .pill { min-width: 0; padding: 5px 7px; gap: 4px; }
  .pill span { font-size: .52rem; }
  .pill strong { font-size: .9rem; }
  .game-layout { display: flex; flex-direction: column; }
  .arena-wrap { order: 0; width: 100%; aspect-ratio: 900 / 560; }
  .left-panel { order: 1; border-right: 0; border-top: 1px solid var(--border); }
  .right-panel { order: 2; border-left: 0; border-top: 1px solid var(--border); }
  .hud-panel { padding: 12px; }
  .hud-panel h2 { display: inline-block; margin: 0 8px 8px 0; font-size: .95rem; }
  .left-panel { display: grid; grid-template-columns: 1fr 1fr; gap: 0 10px; align-items: start; }
  .left-panel h2:first-child, .left-panel .team-list { grid-column: 1; }
  .left-panel .small-heading, .left-panel #objective { grid-column: 2; }
  .left-panel .small-heading { grid-row: 1; }
  .left-panel #objective { grid-row: 2; font-size: .8rem; }
  .team-list { gap: 5px; }
  .team-list li { padding: 5px 7px; font-size: .72rem; }
  .right-panel { display: grid; grid-template-columns: 1fr 1fr; gap: 0 10px; }
  .right-panel h2, .guide-list { grid-column: 1; }
  .guide-list { gap: 5px; }
  .guide-list li { padding: 6px 7px; font-size: .7rem; }
  .battle-panel { grid-column: 2; grid-row: 1 / span 2; margin-top: 0; padding: 8px; }
  .battle-actions { gap: 5px; }
  .battle-actions button { min-height: 34px; font-size: .7rem; }
  .message-box { bottom: 8px; width: 68%; left: auto; right: 7px; transform: none; padding: 7px 9px; font-size: .7rem; }
  .touch-controls { position: absolute; z-index: 3; left: 8px; bottom: 8px; display: flex; align-items: end; gap: 8px; touch-action: none; user-select: none; }
  .dpad { width: 104px; height: 94px; display: grid; grid-template-columns: repeat(3, 32px); grid-template-rows: repeat(3, 29px); gap: 2px; }
  .dpad button, .interact-touch { border: 1px solid rgba(227, 235, 255, .4); background: rgba(17, 26, 45, .78); color: white; box-shadow: 0 2px 7px rgba(0,0,0,.25); font-weight: 900; touch-action: none; }
  .dpad button { border-radius: 9px; }
  .dpad [data-key="arrowup"] { grid-column: 2; grid-row: 1; }
  .dpad [data-key="arrowleft"] { grid-column: 1; grid-row: 2; }
  .dpad [data-key="arrowdown"] { grid-column: 2; grid-row: 2; }
  .dpad [data-key="arrowright"] { grid-column: 3; grid-row: 2; }
  .interact-touch { width: 48px; height: 48px; border-radius: 50%; color: var(--gold); }
  .interact-touch small { color: white; font-size: .47rem; }
}

@media (max-width: 380px) {
  .top-bar { flex-direction: column; }
  .status-row { width: 100%; justify-content: space-between; }
  .pill { flex: 1; }
  .message-box { width: 64%; }
}

